<script>
import UserIcon from '../Board/Mixed/UserIcon'
    export default {
        props: ['targetUser', 'targetBoard', 'hasAuth'],
        data(){
            return{
                render: false
            }  
        },
        components:{
            UserIcon
        },
        mounted() {
            if(this.targetUser){
                localStorage.setItem('invite_user', JSON.stringify(this.targetUser));
            }
            if(this.targetBoard){
                localStorage.setItem('join_board', JSON.stringify(this.targetBoard));
            }
            location.replace(window.location.origin + '/chat')
            // if(this.hasAuth){
